func TestEncoding(t *testing.T) {
	tests := []struct {
		name    string
		encoder encodingFn
	}{
		{"protobuf", newProtobufEncoder().Encode},
		{"avro", newAvroEncoder().Encode},
	}

	dataset := []struct {
		name    string
		payload any
	}{
